# Bounded byte-preserving materializer for frozen Windows workload-analysis-v3.
# It copies only explicit sealed source entries, derives console bytes by exact stream concatenation,
# & emits no qualification claim. Missing build/run tables fail before output publication.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$InputManifestPath,
  [Parameter(Mandatory)][string]$OutputRoot,
  [Parameter(Mandatory)][string]$ReceiptPath,
  [int64]$MaxFileBytes=16777216,
  [int64]$MaxTotalBytes=33554432,
  [int64]$MaxManifestBytes=2097152
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Require([bool]$Ok,[string]$Message){if(-not $Ok){throw $Message}}
function Full([string]$Path){return [IO.Path]::GetFullPath($Path)}
function Leaf([string]$Path,[int64]$Limit){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le $Limit) "bounded/reparse input rejected: $Path";return $item}
function Hash([string]$Path){return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Write-FreshBytes([string]$Path,[byte[]]$Bytes){$full=Full $Path;Require (-not(Test-Path -LiteralPath $full)) "fresh output required: $full";$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$([guid]::NewGuid().ToString('N')).tmp";$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($Bytes,0,$Bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$full)}
function Copy-Bounded([string]$Source,[string]$Destination,[int64]$ExpectedBytes,[string]$ExpectedSha,[int64]$Limit){$src=Leaf $Source $Limit;Require ($src.Length -eq $ExpectedBytes) "source byte count mismatch: $Source";Require ((Hash $src.FullName) -ceq $ExpectedSha.ToLowerInvariant()) "source SHA-256 mismatch: $Source";$dest=Full $Destination;Require (-not(Test-Path -LiteralPath $dest)) "derived output already exists: $dest";$parent=Split-Path -Parent $dest;if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$dest.$([guid]::NewGuid().ToString('N')).tmp";$sourceStream=$null;$output=$null;$copied=[int64]0;try{$sourceStream=[IO.File]::Open($src.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$output=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$buffer=New-Object byte[] 65536;while(($n=$sourceStream.Read($buffer,0,$buffer.Length)) -gt 0){$copied+=$n;Require ($copied -le $Limit) 'stream copy exceeded bound';$output.Write($buffer,0,$n)};$output.Flush($true)}finally{if($output){$output.Dispose()};if($sourceStream){$sourceStream.Dispose()}};Require ($copied -eq $ExpectedBytes) "stream copy count mismatch: $Source";[IO.File]::Move($tmp,$dest);Require ((Hash $dest) -ceq $ExpectedSha.ToLowerInvariant()) "derived SHA-256 mismatch: $dest";return [ordered]@{sourcePath=$src.FullName;destination=$dest;bytes=$copied;sha256=$ExpectedSha.ToLowerInvariant()}}
function Read-Manifest([string]$Path){$item=Leaf $Path $MaxManifestBytes;return ([IO.File]::ReadAllText($item.FullName)|ConvertFrom-Json)}
function RelativeDestination([string]$Value){Require (-not [string]::IsNullOrWhiteSpace($Value)) 'manifest destination missing';Require (-not [IO.Path]::IsPathRooted($Value)) "rooted destination rejected: $Value";$clean=$Value.Replace('/','\');Require (-not ($clean -match '(^|\\)\.\.($|\\)')) "parent destination rejected: $Value";return $clean}
Require ($MaxFileBytes -ge 1024 -and $MaxFileBytes -le 16777216) 'file bound rejected';Require ($MaxTotalBytes -ge $MaxFileBytes -and $MaxTotalBytes -le 33554432) 'total bound rejected'
$manifest=Read-Manifest $InputManifestPath;Require ([string]$manifest.schema -ceq 'sr0-r13-offline-analysis-input-manifest-v1') 'manifest schema mismatch';Require ($null -ne $manifest.entries) 'manifest entries missing';$entries=@($manifest.entries);$required=@('result-workload.txt','presentmon.csv','build.json','r1/meta.json','r1/integrity.json','r1/inputs.csv','r1/frames.csv','r1/bridge_input.csv','r1/ticks.csv','r1/mainactor.csv','r1/inject.csv');$streamNames=@('presentmon-stdout','presentmon-stderr');$seen=@{};$total=[int64]0;$validated=[System.Collections.Generic.List[object]]::new()
foreach($entry in $entries){Require ($null -ne $entry.role -and $null -ne $entry.sourcePath -and $null -ne $entry.destination -and $null -ne $entry.bytes -and $null -ne $entry.sha256) 'manifest entry incomplete';$role=[string]$entry.role;$destination=RelativeDestination ([string]$entry.destination);Require ($role -notmatch '[\\/]') "entry role invalid: $role";Require (-not $seen.ContainsKey($role)) "duplicate role: $role";$seen[$role]=$true;Require ([int64]$entry.bytes -ge 0 -and [int64]$entry.bytes -le $MaxFileBytes) "entry bytes exceed bound: $role";Require ([string]$entry.sha256 -match '^[0-9a-fA-F]{64}$') "entry SHA invalid: $role";$total+=[int64]$entry.bytes;Require ($total -le $MaxTotalBytes) 'manifest total exceeds bound';$validated.Add([ordered]@{role=$role;destination=$destination;sourcePath=Full ([string]$entry.sourcePath);bytes=[int64]$entry.bytes;sha256=([string]$entry.sha256).ToLowerInvariant()})}
foreach($destination in $required){Require (@($validated|Where-Object{$_.destination -ceq $destination}).Count -eq 1) "required parser input missing: $destination"};foreach($entry in $validated){$sourceItem=Leaf $entry.sourcePath $MaxFileBytes;Require ($sourceItem.Length -eq $entry.bytes) "source byte count mismatch: $($entry.role)";Require ((Hash $sourceItem.FullName) -ceq $entry.sha256) "source SHA-256 mismatch: $($entry.role)"};foreach($role in $streamNames){Require (@($validated|Where-Object{$_.role -ceq $role}).Count -eq 1) "sealed stream input missing: $role"};Require ($null -ne $manifest.console -and @($manifest.console.order).Count -eq 2 -and [string]$manifest.console.destination -ceq 'presentmon.console.txt') 'console provenance declaration invalid';Require (([string]$manifest.console.order[0] -ceq 'presentmon-stdout') -and ([string]$manifest.console.order[1] -ceq 'presentmon-stderr')) 'console stream order invalid'
$outRoot=Full $OutputRoot;$receiptFull=Full $ReceiptPath;Require (-not(Test-Path -LiteralPath $outRoot)) "analysis output root must be fresh: $outRoot";Require (-not(Test-Path -LiteralPath $receiptFull)) "analysis receipt must be fresh: $receiptFull";Require (-not($receiptFull.StartsWith($outRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase))) 'receipt must be outside output root';[IO.Directory]::CreateDirectory($outRoot)|Out-Null;$copied=[System.Collections.Generic.List[object]]::new()
foreach($entry in $validated){$destination=Join-Path $outRoot $entry.destination;$copied.Add((Copy-Bounded $entry.sourcePath $destination $entry.bytes $entry.sha256 $MaxFileBytes))}
$consoleOut=Join-Path $outRoot ([string]$manifest.console.destination);Require (-not(Test-Path -LiteralPath $consoleOut)) 'console output already exists';$consoleTmp="$consoleOut.$([guid]::NewGuid().ToString('N')).tmp";$consoleParent=Split-Path -Parent $consoleOut;if(-not(Test-Path -LiteralPath $consoleParent -PathType Container)){[IO.Directory]::CreateDirectory($consoleParent)|Out-Null};$consoleStream=$null;$consoleBytes=[int64]0;try{$consoleStream=[IO.File]::Open($consoleTmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);foreach($role in @('presentmon-stdout','presentmon-stderr')){$entry=@($validated|Where-Object{$_.role -ceq $role})[0];$source=Leaf $entry.sourcePath $MaxFileBytes;$sourceStream=[IO.File]::Open($source.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$buffer=New-Object byte[] 65536;while(($n=$sourceStream.Read($buffer,0,$buffer.Length)) -gt 0){$consoleBytes+=$n;Require ($consoleBytes -le $MaxTotalBytes) 'derived console exceeds bound';$consoleStream.Write($buffer,0,$n)}}finally{$sourceStream.Dispose()}};$consoleStream.Flush($true)}finally{if($consoleStream){$consoleStream.Dispose()}};[IO.File]::Move($consoleTmp,$consoleOut);$consoleHash=Hash $consoleOut
$receipt=[ordered]@{kind='sr0-r13-offline-analysis-inputs-v1';status='materialized-byte-preserving';qualificationHeld=$true;qualificationHoldReason='strict-display-parser-pending';inputManifestPath=(Full $InputManifestPath);inputManifestSha256=(Hash (Full $InputManifestPath));outputRoot=$outRoot;entries=@($copied);console=[ordered]@{destination=$consoleOut;bytes=$consoleBytes;sha256=$consoleHash;order=@('presentmon-stdout','presentmon-stderr');syntheticBytesAdded=0};rawPreserved=$true;qualificationClaim=$false;nativeActions=0;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};Write-FreshBytes $receiptFull ([Text.Encoding]::UTF8.GetBytes(($receipt|ConvertTo-Json -Depth 16)+"`r`n"));$receipt|ConvertTo-Json -Depth 16;exit 0
